fun enabled(m: LongArray) = transitions.indices.filter { reason(m, it) == null }
fun commit(t: Int) {
    history.add(current)
    current = fire(current, t)
        "SIMULATE" -> {
            val steps = (number(w[1], 1, 1000) ?: bad("invalid steps ${w[1]}")).toInt()
            var x = number(w[2], 1, 2147483646) ?: bad("invalid seed ${w[2]}")
            if (w[3] !in listOf("PRIORITY", "RANDOM")) bad("invalid mode ${w[3]}")
            val counts = IntArray(transitions.size)
            var done = 0
            while (done < steps) {
                val es = enabled(current)
                if (es.isEmpty()) {
                    println("dead (steps=$done)")
                    break
                }
                var t = es[0]
                if (w[3] == "RANDOM") {
                    x = x * 48271 % 2147483647
                    t = es[(x % es.size).toInt()]
                } else for (u in es) if (priority[u] > priority[t]) t = u
                commit(t)
                ++counts[t]
                ++done
                println("step $done: ${transitions[t]} -> ${mark(current)}")
            }
            if (done == steps) println("completed (steps=$steps)")
            println(
                "counts: " +
                    transitions.indices.joinToString(" ") {
                        "${transitions[it]}=${counts[it]}"
                    },
            )
